CustomField.formula:
IF(TEXT(VVIP_Category__c) == 'Board Members', 1, 
		IF(VVIP__c == true, 2, 
			IF(TEXT(Segment__c) == 'Premium' && Account.Non_KYC_Customer__c = FALSE, 3, 
				IF(TEXT(Segment__c) == 'Staff'  && Account.Non_KYC_Customer__c = FALSE, 4, 
					IF( Account.Non_KYC_Customer__c == true, 6,
						IF(((Nationality__c == 'PK' || Nationality__c == 'IN' || Nationality__c == 'BD') && (TEXT(Gross_Monthly_Income__c) == '500' || (TEXT(Employment_Status__c) == 'Unemployed' || TEXT(Employment_Status__c) == 'Retired' || TEXT(Employment_Status__c) == 'Student') || (Occupation__c =='Worker' || Occupation__c =='Driver' || Occupation__c =='Helper'))),8,
						5)
					)
				) 
			) 
		) 
)
